begin;
create extension if not exists pgcrypto;
create table if not exists public.app_settings(key text primary key,value jsonb not null default '{}'::jsonb,public_read boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,email text not null,display_name text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.teachers(id text primary key,name text not null,role text not null default '',groups jsonb not null default '[]',specialties jsonb not null default '[]',courses jsonb not null default '[]',tags jsonb not null default '[]',teaching_style text not null default '',profile_image_url text,career_summary text not null default '',verified_title text not null default '',completed_lessons integer not null default 0,active boolean not null default true,sort_order integer not null default 100,certifications jsonb not null default '[]',teaching_assignments jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.teacher_users(user_id uuid primary key references auth.users(id) on delete cascade,teacher_id text not null references public.teachers(id) on update cascade on delete cascade,email text not null unique,active boolean not null default true,last_login_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.teacher_availability(id bigint generated by default as identity primary key,teacher_id text not null references public.teachers(id) on update cascade on delete cascade,day_of_week integer not null check(day_of_week between 0 and 6),start_time time not null,end_time time not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_time>start_time));
create table if not exists public.teacher_closures(id bigint generated by default as identity primary key,teacher_id text not null references public.teachers(id) on update cascade on delete cascade,closure_date date not null,closure_time time,reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.teacher_proofs(teacher_id text primary key references public.teachers(id) on update cascade on delete cascade,pass_rate numeric,applicants integer,passed integer,period text,basis text,verified boolean not null default false,submitted_by_user_id uuid references auth.users(id),submitted_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.reviews(id bigint generated by default as identity primary key,teacher_id text references public.teachers(id) on update cascade on delete set null,teacher_name text,student_display text,cert text,course text,content text not null,tags jsonb not null default '[]',verified boolean not null default false,published boolean not null default false,submission_source text,submitted_by_user_id uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.applications(code text primary key,status text not null default 'PAYMENT_PENDING',cert text,category text,course text,target_label text,target_date date,study_status text,daily_study_time text,weakness text,billing_mode text,start_month date,frequency integer,patterns jsonb not null default '[]',period text,teacher_id text references public.teachers(id) on update cascade on delete set null,teacher_name text,student_name text not null,phone text not null,email text,depositor text,request text,sessions integer not null default 0,months integer not null default 1,normal_unit_price integer not null default 40000,unit_price integer not null default 40000,subtotal integer not null default 0,discount_rate numeric not null default 0,discount_amount integer not null default 0,amount integer not null default 0,policy_version text,agreed_at timestamptz,agreements jsonb not null default '{}',read_confirmations jsonb not null default '{}',metadata jsonb not null default '{}',payment_reported_at timestamptz,payment_confirmed_at timestamptz,approved_at timestamptz,cancelled_at timestamptz,pending_expires_at timestamptz default(now()+interval '24 hours'),hold_expires_at timestamptz,payment_rejected_at timestamptz,payment_rejection_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.application_reservations(id bigint generated by default as identity primary key,application_code text not null references public.applications(code) on delete cascade,teacher_id text not null references public.teachers(id) on update cascade on delete restrict,lesson_date date not null,lesson_time time not null,starts_at timestamptz not null,ends_at timestamptz not null,hold_status text not null default 'PENDING',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.lessons(id bigint generated by default as identity primary key,application_code text not null references public.applications(code) on delete cascade,teacher_id text not null references public.teachers(id) on update cascade on delete restrict,starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'APPROVED',meeting_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.payments(id bigint generated by default as identity primary key,application_code text references public.applications(code) on delete set null,provider_transaction_id text unique,amount integer,depositor text,paid_at timestamptz,match_status text,memo text,raw_payload jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated by default as identity primary key,actor_user_id uuid,actor_email text,action text not null,entity_type text,entity_id text,details jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.notification_logs(id bigint generated by default as identity primary key,application_code text,channel text,recipient text,template text,status text,payload jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.security_events(id bigint generated by default as identity primary key,event_type text not null,fingerprint_hash text not null,success boolean not null default false,details jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.teacher_schedule_change_requests(id bigint generated by default as identity primary key,teacher_id text not null references public.teachers(id) on update cascade on delete cascade,application_code text references public.applications(code) on delete cascade,reservation_id bigint references public.application_reservations(id) on delete set null,current_starts_at timestamptz,requested_date date,requested_time time,reason text,status text not null default 'PENDING',requested_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());

alter table public.application_reservations drop constraint if exists application_reservations_teacher_id_starts_at_key;
create unique index if not exists uq_active_teacher_reservation on public.application_reservations(teacher_id,starts_at) where hold_status in ('PENDING','HELD','APPROVED');
create index if not exists idx_applications_identity on public.applications(student_name,phone,created_at desc);create index if not exists idx_reservations_teacher_start on public.application_reservations(teacher_id,starts_at,hold_status);create index if not exists idx_lessons_teacher_start on public.lessons(teacher_id,starts_at,status);create index if not exists idx_security_rate on public.security_events(event_type,fingerprint_hash,created_at desc);
create or replace function public.report_payment_secure(p_code text,p_phone text) returns jsonb language plpgsql security definer set search_path=public as $$declare a public.applications;begin select * into a from public.applications where code=p_code and regexp_replace(phone,'[^0-9]','','g')=regexp_replace(p_phone,'[^0-9]','','g') for update;if not found then raise exception using errcode='P0002',message='신청 정보를 찾을 수 없습니다.';end if;if a.status not in('PAYMENT_PENDING','PAYMENT_REJECTED')then return to_jsonb(a);end if;update public.applications set status='PAYMENT_REPORTED',payment_reported_at=now(),hold_expires_at=now()+interval '24 hours',updated_at=now() where code=p_code returning * into a;update public.application_reservations set hold_status='HELD',updated_at=now() where application_code=p_code and hold_status='PENDING';insert into public.audit_logs(actor_email,action,entity_type,entity_id)values('customer','PAYMENT_REPORTED','application',p_code);return to_jsonb(a);end$$;
create or replace function public.confirm_payment_secure(p_code text,p_actor_user_id uuid,p_actor_email text,p_source text default 'ADMIN_MANUAL') returns jsonb language plpgsql security definer set search_path=public as $$declare a public.applications;begin update public.applications set status='PAYMENT_CONFIRMED',payment_confirmed_at=now(),updated_at=now() where code=p_code and status in('PAYMENT_REPORTED','PAYMENT_REVIEW','PARTIAL_PAYMENT','OVERPAYMENT') returning * into a;if not found then raise exception using errcode='P0001',message='입금 확인 가능한 상태가 아닙니다.';end if;insert into public.audit_logs(actor_user_id,actor_email,action,entity_type,entity_id,details)values(p_actor_user_id,p_actor_email,'PAYMENT_CONFIRMED','application',p_code,jsonb_build_object('source',p_source));return to_jsonb(a);end$$;
create or replace function public.approve_application_secure(p_code text,p_actor_user_id uuid,p_actor_email text) returns jsonb language plpgsql security definer set search_path=public as $$declare a public.applications;begin select * into a from public.applications where code=p_code and status='PAYMENT_CONFIRMED' for update;if not found then raise exception using errcode='P0001',message='입금 확인 완료 상태에서만 승인할 수 있습니다.';end if;if exists(select 1 from public.application_reservations r join public.lessons l on l.teacher_id=r.teacher_id and l.starts_at=r.starts_at and l.status='APPROVED' where r.application_code=p_code)then raise exception using errcode='P0001',message='이미 확정된 수업과 겹칩니다.';end if;insert into public.lessons(application_code,teacher_id,starts_at,ends_at,status)select application_code,teacher_id,starts_at,ends_at,'APPROVED' from public.application_reservations where application_code=p_code on conflict(teacher_id,starts_at)do nothing;update public.application_reservations set hold_status='APPROVED',updated_at=now() where application_code=p_code;update public.applications set status='CLASS_APPROVED',approved_at=now(),updated_at=now() where code=p_code returning * into a;insert into public.audit_logs(actor_user_id,actor_email,action,entity_type,entity_id)values(p_actor_user_id,p_actor_email,'APPLICATION_APPROVED','application',p_code);return to_jsonb(a);end$$;
create or replace function public.cancel_application_secure(p_code text,p_actor_user_id uuid,p_actor_email text,p_reason text default '') returns jsonb language plpgsql security definer set search_path=public as $$declare a public.applications;begin delete from public.lessons where application_code=p_code;update public.application_reservations set hold_status='RELEASED',updated_at=now() where application_code=p_code;update public.applications set status='CANCELLED',cancelled_at=now(),updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('cancelReason',p_reason) where code=p_code returning * into a;if not found then raise exception using errcode='P0002',message='신청을 찾을 수 없습니다.';end if;insert into public.audit_logs(actor_user_id,actor_email,action,entity_type,entity_id,details)values(p_actor_user_id,p_actor_email,'APPLICATION_CANCELLED','application',p_code,jsonb_build_object('reason',p_reason));return to_jsonb(a);end$$;

create or replace function public.expire_application_holds_secure() returns jsonb language plpgsql security definer set search_path=public as $$declare p integer:=0;h integer:=0;begin
with x as(update public.applications set status='EXPIRED',updated_at=now() where status='PAYMENT_PENDING' and pending_expires_at<=now() returning code) update public.application_reservations set hold_status='RELEASED',updated_at=now() where application_code in(select code from x);get diagnostics p=row_count;
with x as(update public.applications set status='EXPIRED',updated_at=now() where status in('PAYMENT_REPORTED','PAYMENT_REVIEW') and hold_expires_at<=now() returning code) update public.application_reservations set hold_status='RELEASED',updated_at=now() where application_code in(select code from x);get diagnostics h=row_count;
return jsonb_build_object('pendingReleased',p,'heldReleased',h);end$$;

insert into public.app_settings(key,value,public_read)values('bank',jsonb_build_object('bankName','IBK기업은행','accountHolder','정아리','accountNumber','195-120491-01-011'),true)on conflict(key)do update set value=excluded.value,public_read=true,updated_at=now();
do $$declare t text;begin foreach t in array array['app_settings','admin_users','teachers','teacher_users','teacher_availability','teacher_closures','teacher_proofs','reviews','applications','application_reservations','lessons','payments','audit_logs','notification_logs','security_events','teacher_schedule_change_requests'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all privileges on table public.%I from anon, authenticated',t);execute format('grant all privileges on table public.%I to service_role',t);end loop;end$$;
revoke execute on all functions in schema public from public,anon,authenticated;grant execute on all functions in schema public to service_role;
commit;